import copy, bisect
MAX_OFF=4611686018427387903

class Err(Exception):
    def __init__(self,code,frame): self.code=code; self.frame=frame

class R:
    def __init__(self,tr):
        c=tr['config']; self.c=c
        self.early=c['early']; self.overlap=c['overlap']; self.buf=c['buffer_packets']
        self.idle=c['idle_ms']; self.msb=c['max_streams_bidi']; self.msu=c['max_streams_uni']
        self.msd=c['max_stream_data']; self.md=c['max_data']; self.cl=c['crypto_limit']
        self.sent=c['sent']
        self.keys={'I':'live','H':'absent','Z':'live' if self.early else 'absent','A':'absent'}
        self.state='open'; self.code=None; self.at=None; self.source=None; self.peer=None
        self.last=0; self.pending=[]; self.pn={'I':set(),'H':set(),'A':set()}
        self.streams={}; self.total=0
        self.crypto={l:{'highest':0,'bytes':{}} for l in 'IHA'}
        self.res=[]
    def result(self,e,p,st,rs,at,fr):
        self.res.append({'event':e,'packet':p,'status':st,'reason':rs,'at_ms':at,'frame':fr})
    def term(self,st,code,at,e,p,fr,peer=None):
        self.state=st; self.code=code; self.at=at; self.source={'event':e,'packet':p,'frame':fr}; self.peer=peer
        for j in self.pending:
            self.result(j['e'],j['p'],'dropped','CONNECTION_CLOSED',at,None)
        self.pending=[]
    def fail(self,e,p,at,fr,code):
        self.term('closed',code,at,e,p,fr); self.result(e,p,'error',code,at,fr)
    def run(self,events):
        for e,ev in enumerate(events):
            t=ev['t']
            if self.state=='open' and self.idle and t>=self.last+self.idle:
                self.term('idle','IDLE_TIMEOUT',self.last+self.idle,e,None,None)
            if ev['op']=='datagram': self.dgram(e,ev,t)
            elif ev['op']=='key' and self.state=='open': self.dokey(ev,t)
        for j in self.pending:
            self.result(j['e'],j['p'],'buffered','NO_KEYS',j['arr'],None)
        self.pending=[]
        return self.out()
    def dokey(self,ev,t):
        l=ev['level']; a=ev['action']
        if a=='discard':
            self.keys[l]='discarded'
            self.pending=[j for j in self.pending if not (j['level']==l and not self.result(j['e'],j['p'],'dropped','KEYS_DISCARDED',t,None))]
        else:
            if self.keys[l]=='absent':
                self.keys[l]='live'
                while True:
                    idx=None
                    for i,j in enumerate(self.pending):
                        if j['level']==l: idx=i; break
                    if idx is None: break
                    j=self.pending.pop(idx)
                    self.packet(j['e'],j['p'],j['pkt'],t,j['size'],True)
    def dgram(self,e,ev,t):
        ps=ev['packets']
        if self.state!='open':
            for p in range(len(ps)): self.result(e,p,'dropped','CONNECTION_CLOSED',t,None)
            return
        if any(ps[p]['level']=='A' for p in range(len(ps)-1)):
            for p in range(len(ps)): self.result(e,p,'dropped','LAYOUT',t,None)
            return
        for p,pkt in enumerate(ps):
            if self.state!='open':
                self.result(e,p,'dropped','CONNECTION_CLOSED',t,None); continue
            self.packet(e,p,pkt,t,ev['bytes'],False)
    def packet(self,e,p,pkt,t,size,drained):
        l=pkt['level']; pn=pkt['pn']
        if not drained:
            if l=='I' and size<1200:
                self.result(e,p,'dropped','INITIAL_TOO_SMALL',t,None); return
            if l=='Z' and not self.early:
                self.result(e,p,'dropped','EARLY_REJECTED',t,None); return
        ks=self.keys[l]
        if ks=='discarded':
            self.result(e,p,'dropped','KEYS_DISCARDED',t,None); return
        if ks=='absent':
            if len(self.pending)<self.buf:
                self.pending.append({'e':e,'p':p,'arr':t,'pkt':pkt,'level':l,'size':size})
            else:
                self.result(e,p,'dropped','BUFFER_FULL',t,None)
            return
        if not pkt['auth']:
            self.result(e,p,'dropped','AUTH',t,None); return
        space='I' if l=='I' else 'H' if l=='H' else 'A'
        if pn in self.pn[space]:
            self.result(e,p,'duplicate','DUPLICATE',t,None); return
        self.frames(e,p,t,pkt,self.pn[space])
    def frames(self,e,p,t,pkt,pnset):
        l=pkt['level']; fs=pkt['frames']
        if not fs:
            self.fail(e,p,t,None,'FRAME_ENCODING_ERROR'); return
        for i,f in enumerate(fs):
            if f['type']=='UNKNOWN': self.fail(e,p,t,i,'FRAME_ENCODING_ERROR'); return
            if not allowed(f,l): self.fail(e,p,t,i,'PROTOCOL_VIOLATION'); return
        snap=(copy.deepcopy(self.streams),self.total,copy.deepcopy(self.crypto))
        try:
            for i,f in enumerate(fs):
                ty=f['type']
                if ty in ('PADDING','PING'): continue
                if ty=='CLOSE':
                    pnset.add(pkt['pn']); self.last=t
                    self.term('closed','PEER_APPLICATION_CLOSE' if f['app'] else 'PEER_TRANSPORT_CLOSE',t,e,p,i,peer=f['code'])
                    self.result(e,p,'accepted','OK',t,None); return
                if ty=='ACK':
                    rs=f['ranges']
                    if not rs: raise Err('FRAME_ENCODING_ERROR',i)
                    ph=None
                    for lo,hi in rs:
                        if lo>hi or (ph is not None and lo<=ph+1): raise Err('FRAME_ENCODING_ERROR',i)
                        ph=hi
                    sent=self.sent[l]
                    for lo,hi in rs:
                        ok=False
                        for a,b in sent:
                            if a<=lo and hi<=b: ok=True; break
                        if not ok: raise Err('PROTOCOL_VIOLATION',i)
                    continue
                if ty=='CRYPTO':
                    data=bytes.fromhex(f['data_hex']); end=f['offset']+len(data)
                    if end>MAX_OFF: raise Err('FRAME_ENCODING_ERROR',i)
                    if end>self.cl: raise Err('CRYPTO_BUFFER_EXCEEDED',i)
                    st=self.crypto[l]
                    self.store(st['bytes'],f['offset'],data,i)
                    if end>st['highest']: st['highest']=end
                    continue
                if ty=='STREAM':
                    sid=f['id']; self.check(sid,True,i)
                    ent=self.streams.get(sid)
                    if ent is None:
                        ent={'id':sid,'highest':0,'final_size':None,'reset':False,'stopped':False,'bytes':{}}
                        self.streams[sid]=ent
                    data=bytes.fromhex(f['data_hex']); end=f['offset']+len(data); fin=f['fin']
                    if end>MAX_OFF: raise Err('FRAME_ENCODING_ERROR',i)
                    if ent['final_size'] is not None and (end>ent['final_size'] or (fin and end!=ent['final_size'])):
                        raise Err('FINAL_SIZE_ERROR',i)
                    old=ent['highest']
                    if fin and end<old: raise Err('FINAL_SIZE_ERROR',i)
                    if end>self.msd: raise Err('FLOW_CONTROL_ERROR',i)
                    nh=max(old,end); nt=self.total-old+nh
                    if nt>self.md: raise Err('FLOW_CONTROL_ERROR',i)
                    if not ent['reset']: self.store(ent['bytes'],f['offset'],data,i)
                    ent['highest']=nh; self.total=nt
                    if fin: ent['final_size']=end
                    continue
                if ty=='RESET_STREAM':
                    sid=f['id']; self.check(sid,True,i)
                    ent=self.streams.get(sid)
                    if ent is None:
                        ent={'id':sid,'highest':0,'final_size':None,'reset':False,'stopped':False,'bytes':{}}
                        self.streams[sid]=ent
                    sz=f['final_size']
                    if ent['final_size'] is not None and sz!=ent['final_size']: raise Err('FINAL_SIZE_ERROR',i)
                    old=ent['highest']
                    if sz<old: raise Err('FINAL_SIZE_ERROR',i)
                    if sz>self.msd: raise Err('FLOW_CONTROL_ERROR',i)
                    nh=max(old,sz); nt=self.total-old+nh
                    if nt>self.md: raise Err('FLOW_CONTROL_ERROR',i)
                    ent['highest']=nh; self.total=nt; ent['final_size']=sz; ent['reset']=True
                    continue
                if ty=='STOP_SENDING':
                    sid=f['id']
                    if sid%4!=0: raise Err('STREAM_STATE_ERROR',i)
                    if sid//4+1>self.msb: raise Err('STREAM_LIMIT_ERROR',i)
                    ent=self.streams.get(sid)
                    if ent is None:
                        ent={'id':sid,'highest':0,'final_size':None,'reset':False,'stopped':False,'bytes':{}}
                        self.streams[sid]=ent
                    ent['stopped']=True
                    continue
                raise Err('PROTOCOL_VIOLATION',i)
        except Err as er:
            self.streams,self.total,self.crypto=snap
            self.fail(e,p,t,er.frame,er.code); return
        pnset.add(pkt['pn']); self.last=t
        self.result(e,p,'accepted','OK',t,None)
    def check(self,sid,uni,i):
        m=sid%4
        if m==0: lim=self.msb
        elif m==2 and uni: lim=self.msu
        else: raise Err('STREAM_STATE_ERROR',i)
        if sid//4+1>lim: raise Err('STREAM_LIMIT_ERROR',i)
    def store(self,bmap,off,data,i):
        for k,b in enumerate(data):
            o=off+k
            if o in bmap:
                if bmap[o]!=b:
                    if self.overlap=='reject': raise Err('PROTOCOL_VIOLATION',i)
            else: bmap[o]=b
    def out(self):
        def pref(bmap):
            d=0
            while d in bmap: d+=1
            return bytes(bmap[i] for i in range(d)).hex() if d else ''
        streams=[{'id':sid,'highest':s['highest'],'final_size':s['final_size'],'reset':s['reset'],'stopped':s['stopped'],'delivered_hex':pref(s['bytes'])} for sid,s in sorted(self.streams.items())]
        crypto=[{'level':l,'highest':self.crypto[l]['highest'],'contiguous_hex':pref(self.crypto[l]['bytes'])} for l in 'IHA']
        conn={'state':self.state,'code':self.code,'at_ms':self.at,'source':self.source,'peer_code':self.peer,'last_activity_ms':self.last}
        return {'packets':sorted(self.res,key=lambda r:(r['event'],r['packet'])),'connection':conn,
                'keys':dict(self.keys),'received_total':self.total,'streams':streams,'crypto':crypto}

def allowed(f,l):
    ty=f['type']
    if ty in ('PADDING','PING'): return True
    if ty in ('ACK','CRYPTO'): return l in ('I','H','A')
    if ty in ('STREAM','RESET_STREAM','STOP_SENDING'): return l in ('Z','A')
    if ty=='CLOSE': return (not f['app']) or l in ('Z','A')
    if ty=='HANDSHAKE_DONE': return False
    return False
